from pathlib import Path
p=Path('sdxl_train.py').read_text(encoding='utf-8')
p=p.replace('import argparse,contextlib,gc,json,os,time,statistics,threading,subprocess','import argparse,contextlib,gc,json,os,time,statistics,threading,subprocess,random,hashlib,shutil')
p=p.replace("    args=ap.parse_args();rank=", "    ap.add_argument('--lr-student',type=float,default=5e-7);ap.add_argument('--lr-fake',type=float,default=5e-7)\n    ap.add_argument('--pcm-weight',type=float,default=10);ap.add_argument('--fake-ratio',type=int,default=5)\n    ap.add_argument('--max-grad-norm',type=float,default=10);ap.add_argument('--seed',type=int,default=20261017)\n    ap.add_argument('--teacher-cfg',type=float,default=8);ap.add_argument('--train-samples',type=int,default=96)\n    ap.add_argument('--no-save',action='store_true')\n    args=ap.parse_args();rank=")
p=p.replace("    (out/f'worker_rank{rank}.pid').write_text(str(os.getpid()))", "    assert not (out/'summary.json').exists(),'Refusing to overwrite a completed trial'\n    if rank==0:\n        (out/'args.json').write_text(json.dumps(vars(args),indent=2))\n        shutil.copyfile(__file__,out/'training_source.py')\n        (out/'training_source.sha256').write_text(hashlib.sha256(Path(__file__).read_bytes()).hexdigest())\n    (out/f'worker_rank{rank}.pid').write_text(str(os.getpid()))")
p=p.replace('torch.manual_seed(20261017)','torch.manual_seed(args.seed)')
p=p.replace('lr=5e-7,betas=', 'lr=args.lr_student,betas=').replace('lr=1e-7,betas=', 'lr=args.lr_fake,betas=')
p=p.replace('torch.manual_seed(20261017+rank)','torch.manual_seed(args.seed+rank)\n    length_rng=random.Random(args.seed)')
p=p.replace('tau=args.crossover;knots=[999,tau,499,249,-1];assert 999>tau>499','tau=args.crossover;knots=[999,tau,round(2*tau/3),round(tau/3),-1];assert 978>=tau>40\n    assert args.fake_ratio>0 and args.train_samples<=len(data["latents"])\n    train_order=random.Random(args.seed+31).sample(range(args.train_samples),args.train_samples)\n    if rank==0:(out/"data_split.json").write_text(json.dumps({"train_cache_indices":train_order,"validation_cache_indices":list(range(args.train_samples,len(data["latents"])))},indent=2))')
p=p.replace('return e_un+8.0*(e_cond-e_un)','return e_un+args.teacher_cfg*(e_cond-e_un)')
p=p.replace('def rollout(c,shape,grad=False):','def rollout(c,shape,grad=False,length=4):')
p=p.replace('for i,(t,s) in enumerate(zip(knots[:-1],knots[1:])):', 'active=knots[:length]+[-1]\n        for i,(t,s) in enumerate(zip(active[:-1],active[1:])):')
p=p.replace('grad and i==3','grad and i==length-1')
p=p.replace("idx=(iteration*world+rank)%len(data['latents'])", "idx=train_order[(iteration*world+rank)%len(train_order)]")
p=p.replace('is_student=iteration%5==4','is_student=iteration%(args.fake_ratio+1)==args.fake_ratio')
p=p.replace('generated=rollout(c,x_real.shape,grad=True)','rollout_length=length_rng.choice([2,3,4])\n            generated=rollout(c,x_real.shape,grad=True,length=rollout_length)')
p=p.replace('(10.0*loss_pcm).backward()','(args.pcm_weight*loss_pcm).backward()')
p=p.replace("opt_g.step();phase='student';loss=loss_dmd+10*loss_pcm", "clip_scale=min(1.0,args.max_grad_norm/(grad_norm+1e-12))\n            for parameter in student.parameters():\n                if parameter.grad is not None:parameter.grad.mul_(clip_scale)\n            opt_g.step();phase='student';loss=loss_dmd+args.pcm_weight*loss_pcm")
p=p.replace("'dmd_t':t.item()}","'dmd_t':t.item(),'rollout_length':rollout_length,'clip_scale':clip_scale}")
p=p.replace("opt_f.step();phase='fake_score';extras={'fake_t':t.item()}", "clip_scale=min(1.0,args.max_grad_norm/(grad_norm+1e-12))\n            for parameter in fake.parameters():\n                if parameter.grad is not None:parameter.grad.mul_(clip_scale)\n            opt_f.step();phase='fake_score';extras={'fake_t':t.item(),'clip_scale':clip_scale}")
p=p.replace("'pcm_weight':10,'lr_student':5e-7,'lr_fake':1e-7", "'pcm_weight':args.pcm_weight,'lr_student':args.lr_student,'lr_fake':args.lr_fake,'fake_to_student_ratio':args.fake_ratio,'max_grad_norm':args.max_grad_norm,'train_cache_samples':args.train_samples,'validation_cache_samples':len(data['latents'])-args.train_samples,'seed':args.seed")
p=p.replace("'teacher_cfg':8", "'teacher_cfg':args.teacher_cfg")
p=p.replace("'rollout_gradient':'last low-noise step only; relay detached'", "'rollout_gradient':'uniform rollout length m in {2,3,4}, last low-noise step only; relay detached'")
# Maintain identical collective order across ranks via the shared Python length RNG.
Path('sdxl_hparam_train.py').write_text(p,encoding='utf-8')
compile(p,'sdxl_hparam_train.py','exec')
